import json
from pathlib import Path
from concord import claims
ROOT = Path(__file__).resolve().parents[2]
D = ROOT / "data" / "derived" / "round2" / "tidal_trend"
r = json.load(open(D / "results.json")); c = json.load(open(D / "complaints_by_day_zip.json")); t = json.load(open(D / "battery_daily_max_mhhw.json"))
p = r["primary"]; a = r["part2a"]
sources = [s for s in c["sources"] if s.get("dataset")][:1] + [s for s in c["sources"] if s.get("dataset") == "erm2-nwe9"][:1]
sources = [dict(s, note="first of the per-year queries; the year-by-year queries are in complaints_by_day_zip.json") for s in sources]
sources += [{"kind": "noaa-co-ops", "station": "8518750 The Battery", "product": "hourly_height, datum MHHW, metric, lst_ldt", "years": "2010-2025", "n_requests": len(t["sources"]), "first_url": t["sources"][0]["url"], "fetched": t["sources"][0]["fetched"], "data_access": "open"},
            {"kind": "noaa-co-ops", "product": "datums (mdapi) and sealvltrends (dpapi) for 8518750", "note": "MHHW 2.543 m, MLLW 1.002 m above station datum; trend 1.16 +/- 0.02 in/decade = 2.95 +/- 0.05 mm/yr, 1856-2025"},
            {"kind": "noaa-ghcnd", "stations": "USW00094728, USW00094789", "dataset": "GHCN-Daily v3 (NCEI), doi:10.7289/V5D21VHZ"}]
out = claims.outcome({
 "id": "further-tidal-flooding-trend", "verdict": "confirmed",
 "city_effect": {"label": "Rate ratio of dry-day street-flooding and catch-basin complaints in the coastal ZIP set per 10 cm of Battery daily maximum above 0.35 m over MHHW, 2010-2019 held-out period",
                 "estimate": p["tidal"]["rr"], "lo": p["tidal"]["lo"], "hi": p["tidal"]["hi"], "scale": "rate ratio per 10 cm above knot", "null": 1, "n": p["n_days"]},
 "graph_effect": None, "sources": sources,
 "prediction_scored": f"Part 1 hit on direction and on the support condition (tidal {p['tidal']['rr']:.2f}, {p['tidal']['lo']:.2f} to {p['tidal']['hi']:.2f}; tidal over other {p['ratio']['rr']:.2f}, {p['ratio']['lo']:.2f} to {p['ratio']['hi']:.2f}); the tidal estimate sits at the top of the registered range 1.10 to 2.0; the other-ZIP estimate ({p['placebo']['rr']:.2f}, {p['placebo']['lo']:.2f} to {p['placebo']['hi']:.2f}) is a miss against the registered 0.95 to 1.10. Part 2a partial: OLS slope {a['ols']['slope']:.2f} ({a['ols']['lo']:.2f} to {a['ols']['hi']:.2f}) days per year per year contains both the implied 0.55 and zero. Part 2b: no association (Spearman {r['part2b']['spearman_rho']:.2f}, p {r['part2b']['spearman_p']:.2f}), as registered, not testable.",
 "settle": "Wind and local rain are the main untested rivals for the tide effect (the other-ZIP set also rises, 1.15 per 10 cm, and contains waterfront ZIPs); a Jamaica Bay or Rockaway gauge, hourly local rain and event-level matching with FloodNet would separate them. For the trend, more years: 16 annual counts cannot separate 0.55 days/yr/yr from zero.",
 "research_needed": [
  {"question": "Does 311 reporting of tidal flooding rise with the tide after wind set-up and hyperlocal rain are controlled?", "data": "CO-OPS Jamaica Bay-area gauges, MesoNet or radar rainfall, 311, FloodNet", "design": "same hinge model with local gauge and radar rain", "priority": "high"},
  {"question": "What health outcomes follow tidal nuisance flooding (as opposed to disaster flooding) in New York City?", "data": "NYC DOHMH syndromic surveillance by ZIP, 311 flood days", "design": "case-crossover on dry high-tide days; the graph holds only disaster-flood outcomes", "priority": "medium"}],
 "figures": ["figures/round2/further-tidal-flooding-trend.png"],
 "notes": f"Held-out sample: {r['_sample']['dry_days']} dry days in 2010-2019 (Sandy window 29 Oct to 30 Nov 2012 dropped), {r['_sample']['dry_days_H_ge_knot']} with maximum at or above 0.35 m MHHW, {r['_sample']['c3_tidal']} C3 complaints in the 8 coastal ZIPs and {r['_sample']['c3_placebo']} in the other ZIPs; minimum-data rule met. Only 7 dry days reached the NOS minor level (0.563 m), so the first claim's threshold could not be used. Registered 311 queries were run with agency = 'DEP' added and in one-year chunks because the unrestricted upper() LIKE query timed out; all matching records in 2010-2019 for the case-sensitive patterns belong to DEP (249,360 records including sewer backups). Checks, tidal rate ratio per 10 cm: knot 0.30 {r['check_knot_30']['tidal']['rr']:.2f}, 0.40 {r['check_knot_40']['tidal']['rr']:.2f}, 0.45 {r['check_knot_45']['tidal']['rr']:.2f}; street flooding only {r['check_C1']['tidal']['rr']:.2f} ({r['check_C1']['tidal']['lo']:.2f} to {r['check_C1']['tidal']['hi']:.2f}); with sewer backups {r['check_C4']['tidal']['rr']:.2f}; log-linear over all dry days {r['check_loglinear_all_days_per10cm']['tidal']['rr']:.2f} ({r['check_loglinear_all_days_per10cm']['tidal']['lo']:.2f} to {r['check_loglinear_all_days_per10cm']['tidal']['hi']:.2f}); 2020-2025 in-sample {r['comparison_2020_2025_not_held_out']['tidal']['rr']:.2f}; shifted-tide placebos {r['placebo_shift7']['tidal']['rr']:.2f} and {r['placebo_shift100']['tidal']['rr']:.2f}. The registered shape was flat below the knot, but the band model shows the complaint rate already above the reference in 0.30 to 0.35 m (rate ratio {r['bands_tidal']['band1']['rr']:.2f}), so the rise is smooth, not a threshold. Part 2a: annual counts 2010-2025 range from 11 to 41 (2024); detrending the tide by 2.95 mm/yr gives a slope of {a['detrended_ols']['slope']:.2f} ({a['detrended_ols']['lo']:.2f} to {a['detrended_ols']['hi']:.2f}); the gauge's own annual-mean slope over 2010-2025 is {a['annual_mean_daily_max_slope_mm_per_yr']:.1f} mm/yr, above the long-term 2.95. The verdict is decided by part 1 alone as registered."
})
print(out)
